@push('scripts')<script>(()=>{const field=document.getElementById('reference-source');if(!field)return;const contracts=@json($referenceContracts);const form=field.form;function update(){for(const [selector,show] of [['[data-contract-reference]',field.value!=='documento'],['[data-contract-specific]',field.value==='especifico'],['[data-document-reference]',field.value==='documento']])document.querySelectorAll(selector).forEach(el=>{el.hidden=!show;el.querySelectorAll('input,select').forEach(input=>input.disabled=!show);});const preview=document.getElementById('reference-preview');let text='';if(field.value==='documento'){text='Vigencia indicada manualmente: '+(form.elements.fecha_efectiva.value||'falta seleccionar fecha')+'. Confírmala leyendo el documento.';}else{const dateField=form.elements.fecha_campo.value;let selected;if(field.value==='especifico')selected=contracts.find(c=>String(c.id)===form.elements.contract_id.value);else if(contracts.every(c=>c[dateField])){const sorted=[...contracts].sort((a,b)=>a[dateField].localeCompare(b[dateField])||a.number-b.number);selected=field.value==='primero'?sorted[0]:sorted[sorted.length-1];}text=selected&&selected[dateField]?'Se guardará '+selected[dateField]+' del contrato #'+selected.number+'.':'No se puede determinar la fecha. Elige un contrato con fecha informada.';}preview.textContent=text;}form.addEventListener('change',()=>{form.elements.confirmed.checked=false;update();});form.elements.confirmed.addEventListener('change',e=>e.stopPropagation());update();})();</script>@endpush
